export const StreamEventSnapshot = "snapshot";
export const StreamEventAP = "ap";
export const StreamEventEvent = "event";
export const StreamEventConfig = "config";
export const StreamEventPush = "push";
export const StreamEventPending = "pending";
/**
 * SSE event names of GET /api/sites/$id/stream (design §4.10).
 */
export type StreamEvent = typeof StreamEventSnapshot | typeof StreamEventAP | typeof StreamEventEvent | typeof StreamEventConfig | typeof StreamEventPush | typeof StreamEventPending;
/**
 * APLive is the `ap` event and one entry of a snapshot.
 */
export interface APLive {
  id: string;
  status: APStatus;
  connected: boolean;
  applied_revision: number /* uint64 */;
  config_revision: number /* uint64 */;
  last_error: string;
  client_count: number /* int */;
  uptime_seconds: number /* uint64 */;
  lan_ip: string;
  remote_address: string;
  radios: RadioSummary[];
  seen_at: string /* RFC3339 */;
}
/**
 * StreamSnapshot is the `snapshot` event: on connect and after any
 * `config` event.
 */
export interface StreamSnapshot {
  site_id: string;
  revision: number /* uint64 */;
  aps: APLive[];
}
/**
 * EventSummary is the `event` event: an EventView without the client MAC,
 * WLAN and data. The drawer fetches the full event.
 */
export interface EventSummary {
  id: string;
  ap_id: string;
  kind: string;
  severity: Severity;
  title: string;
  first_seen: string /* RFC3339 */;
  last_seen: string /* RFC3339 */;
  count: number /* int */;
  resolved_by: string | null;
  has_client: boolean;
}
/**
 * ActorKind says who made a change.
 */
export const ActorKindSession = "session";
export const ActorKindToken = "token";
export const ActorKindSystem = "system";
export type ActorKind = typeof ActorKindSession | typeof ActorKindToken | typeof ActorKindSystem;
/**
 * Actor is who made a change (no secrets).
 */
export interface Actor {
  kind: ActorKind;
  name: string;
}
/**
 * ConfigEvent is the `config` event, sent after a committed mutation.
 * Kind is for example "wlan.updated", "site.updated", "ap.updated".
 */
export interface ConfigEvent {
  revision: number /* uint64 */;
  kind: string;
  object_id: string;
  affected_aps: string[];
  actor: Actor;
}
/**
 * PushState is a config push lifecycle state (design §5.6, phase 2).
 */
export const PushStateNotified = "notified";
export const PushStateFetched = "fetched";
export const PushStateApplied = "applied";
export const PushStateRejected = "rejected";
export const PushStateFallbackReconnect = "fallback_reconnect";
export const PushStateTimeout = "timeout";
export type PushState = typeof PushStateNotified | typeof PushStateFetched | typeof PushStateApplied | typeof PushStateRejected | typeof PushStateFallbackReconnect | typeof PushStateTimeout;
/**
 * PushEvent is the `push` event (phase 2).
 */
export interface PushEvent {
  ap_id: string;
  revision: number /* uint64 */;
  state: PushState;
  error: string;
}
/**
 * PendingEvent is the `pending` event: the pending-AP count changed.
 */
export interface PendingEvent {
  count: number /* int */;
}

