// source: system.go

/**
 * CertView describes the AP-facing leaf certificate.
 */
export interface CertView {
  subject: string;
  sans: string[];
  issuer: string;
  not_after: string /* RFC3339 */;
}
/**
 * ChainCertRole is the role of a CA certificate in the served chain or the
 * onboarding bundle.
 */
export const ChainCertRoleIntermediate = "intermediate";
export const ChainCertRoleRoot = "root";
export type ChainCertRole = typeof ChainCertRoleIntermediate | typeof ChainCertRoleRoot;
/**
 * ChainCert is one CA certificate in the served chain or onboarding bundle.
 */
export interface ChainCert {
  subject: string;
  not_after: string /* RFC3339 */;
  role: ChainCertRole;
}
/**
 * WSSView is the AP endpoint card.
 */
export interface WSSView {
  /**
   * URL is the WSS URL APs are configured with ("" when -ap-url is not
   * set).
   */
  url: string;
  listen: string;
  cert: CertView;
  chain: ChainCert[];
  /**
   * Sessions is the number of connected AP sessions.
   */
  sessions: number /* int */;
}
/**
 * DBView is the database card.
 */
export interface DBView {
  path: string;
  size_bytes: number /* int64 */;
  free_bytes: number /* uint64 */;
  schema: number /* uint64 */;
  compat: number /* uint64 */;
  /**
   * RollbackWithoutRestore is true while meta.compat is 1: an older
   * release can run this database without restoring a backup first.
   */
  rollback_without_restore: boolean;
  retention: { [key: string]: string};
}
/**
 * PreMigrationCopy is one controller.db.pre-v<N>-<ts> file.
 */
export interface PreMigrationCopy {
  name: string;
  size_bytes: number /* int64 */;
}
/**
 * BackupView is the backups card.
 */
export interface BackupView {
  last_success: string | null;
  /**
   * Next is the next scheduled snapshot; null when snapshots are off.
   */
  next: string | null;
  /**
   * Interval is the snapshot interval as a Go duration ("24h0m0s"), ""
   * when snapshots are off.
   */
  interval: string;
  keep: number /* int */;
  max_bytes: number /* int64 */;
  used_bytes: number /* int64 */;
  count: number /* int */;
  dir: string;
  /**
   * LastError is the reason the last scheduled snapshot was skipped or
   * failed; "" after a success.
   */
  last_error: string;
  pre_migration: PreMigrationCopy[];
}
/**
 * MetricsClients is the client metric mode.
 */
export const MetricsClientsOff = "off";
export const MetricsClientsAggregate = "aggregate";
export const MetricsClientsPerClient = "per-client";
export type MetricsClients = typeof MetricsClientsOff | typeof MetricsClientsAggregate | typeof MetricsClientsPerClient;
/**
 * MetricsView is the metrics card.
 */
export interface MetricsView {
  listen: string;
  remote: boolean;
  names: boolean;
  clients: MetricsClients;
}
/**
 * MigrationState is meta.migration_state.state.
 */
export const MigrationStateNotRun = "not_run";
export const MigrationStateCommitted = "committed";
export const MigrationStateLegacy = "legacy";
export type MigrationState = typeof MigrationStateNotRun | typeof MigrationStateCommitted | typeof MigrationStateLegacy;
/**
 * MigrationView is the migration card.
 */
export interface MigrationView {
  state: MigrationState;
  reason: string;
  report_available: boolean;
}
/**
 * SystemView is GET /api/system (design §3.14).
 */
export interface SystemView {
  version: string;
  commit: string;
  go: string;
  started_at: string /* RFC3339 */;
  ready: boolean;
  wss: WSSView;
  /**
   * DNSMode is true when dismist serves AP DNS for the stock Mist name.
   */
  dns_mode: boolean;
  trusted_proxies: string[];
  db: DBView;
  backup: BackupView;
  metrics: MetricsView;
  migration: MigrationView;
}
/**
 * CAPem is one CA certificate for an AP's trust bundle.
 */
export interface CAPem {
  name: string;
  pem: string;
}
/**
 * OnboardingView is GET /api/onboarding: what an AP needs to reach this
 * controller. CAPems are the CA certificates of the served chain (the
 * issuing roots and intermediates, or the controller's own CA); the CLI adds
 * them to the AP's stock Mist bundle. CloudINI is a cloud.ini for
 * /rw/etc/mist/ep-control, "" when the WSS URL is not known.
 */
export interface OnboardingView {
  wss_url: string;
  dns_mode: boolean;
  ca_pems: CAPem[];
  cloud_ini: string;
}
/**
 * HealthView is the body of /healthz and of a passing /readyz.
 */
export interface HealthView {
  status: string;
}
